rss.channel:
    {{ .Site.Title }} (近期更新)
    {{ .Site.BaseURL }}
    The latest 10 posts from {{ .Site.Title }}
    Hugo -- gohugo.io
    {{ with .Site.LanguageCode }}{{.}}{{end}}
    {{- with .OutputFormats.Get "RSS" -}}
    {{ printf "" .Permalink .MediaType | safeHTML }}
    {{- end -}}
    {{ range first 10 .Site.RegularPages }}


      {{ .Title }}
      {{ .Permalink }}
      {{ .Date.Format "Mon, 02 Jan 2006 15:04:05 -0700" | safeHTML }}
      {{ .Permalink }}
      {{- $summary := replaceRE `(?s).*?` "" .Summary -}}
      {{- $summary = replaceRE `(?s)<figure\b.*?` "" $summary -}}
      {{- $summary = replaceRE `(?s)<picture\b.*?` "" $summary -}}
      {{- $summary = replaceRE `(?s)]*>\s*]*>\s*` "" $summary -}}
      {{- $summary = replaceRE `(?s)]*>` "" $summary -}}
      {{ $summary | plainify | htmlEscape }}
      {{- $content := .Content -}}
      {{- $sidenotes := findRE `(?s).*?` $content -}}
      {{- if $sidenotes -}}
        {{- $content = replaceRE `(?s).*?` "" $content -}}
        {{- $footnotes := `
` -}}
        {{- range $sidenotes -}}
          {{- $text := replaceRE `(?s)(.*?)` "$1" . -}}
          {{- $footnotes = printf "%s
%s" $footnotes $text -}}
        {{- end -}}
        {{- $footnotes = printf "%s" $footnotes -}}
        {{- $content = printf "%s%s" $content $footnotes -}}
      {{- end -}}
      {{- $base := strings.TrimSuffix "/" $.Site.BaseURL -}}
      {{- $content = replaceRE `src=["']/(.*?)["']` (printf `src="%s/$1"` $base) $content -}}
      {{- $content = replaceRE `src=["'](?:\./)?assets/(.*?)["']` (printf `src="%s/blog/assets/$1"` $base) $content -}}
      {{ printf `%s<br><br><div style="text-align: right;"><a href="%s" style="text-decoration: underline;">看完了，进来坐坐？</a></div>` $content .Permalink | safeHTML }}

    {{ end }}
